flowchart TD
  START["Need a named type?"] --> Q1{"Union, tuple, or mapped type?"}
  Q1 -->|Yes| TYPE["Use type alias"]
  Q1 -->|No| Q2{"Need declaration merging?"}
  Q2 -->|Yes| IFACE["Use interface"]
  Q2 -->|No| Q3{"Class will implement it?"}
  Q3 -->|Yes| IFACE
  Q3 -->|No| EITHER["Either works — team convention"]

snippet.code:
interface User {
  id: string;
  name: string;
  email?: string;
}

interface Admin extends User {
  permissions: string[];
}

class UserService implements User {
  id = "";
  name = "";
}

type ID = string | number;

type ApiResponse<T> =
  | { ok: true; data: T }
  | { ok: false; error: string };

type Point = [number, number];

type ReadonlyUser = Readonly<User>;

// In your-app.d.ts
interface Window {
  myAppConfig: { apiUrl: string };
}

// Elsewhere — both declarations merge:
interface Window {
  analyticsId: string;
}

// Window now has myAppConfig AND analyticsId
